package org.jkiss.dbeaver.teststudio.core;
import com.google.gson.*;import java.util.*;import org.eclipse.core.runtime.*;import org.jkiss.dbeaver.teststudio.spi.*;
final class StudioExtensionRegistry{private StudioBridge bridge;private final List<TestStudioAiProvider> ai=new ArrayList<>();private final List<DatabaseAdapter> databases=new ArrayList<>();StudioExtensionRegistry(){load("org.jkiss.dbeaver.teststudio.core.bridge",StudioBridge.class,o->{if(bridge==null||o.priority()<bridge.priority())bridge=o;});load("org.jkiss.dbeaver.teststudio.core.aiProvider",TestStudioAiProvider.class,ai::add);load("org.jkiss.dbeaver.teststudio.core.databaseAdapter",DatabaseAdapter.class,databases::add);ai.sort(Comparator.comparingInt(TestStudioAiProvider::priority));databases.sort(Comparator.comparingInt(DatabaseAdapter::priority));}StudioBridge bridge(){if(bridge==null)throw new IllegalStateException("No compatible DBeaver Test Studio bridge is installed");return bridge;}JsonObject capabilities(){JsonObject r=new JsonObject();if(bridge==null){r.addProperty("bridge","unavailable");}else{r.addProperty("bridge",bridge.id());r.add("bridge_capabilities",bridge.capabilities());}r.add("ai",describeAi());r.add("databases",describeDatabases());return r;}JsonObject describeAi(){JsonArray a=new JsonArray();for(TestStudioAiProvider p:ai){JsonObject i=new JsonObject();i.addProperty("id",p.id());i.add("capabilities",p.capabilities());a.add(i);}JsonObject r=new JsonObject();r.addProperty("count",a.size());r.add("providers",a);return r;}JsonObject describeDatabases(){JsonArray a=new JsonArray();for(DatabaseAdapter p:databases){JsonObject i=new JsonObject();i.addProperty("id",p.id());i.add("capabilities",p.capabilities());a.add(i);}JsonObject r=new JsonObject();r.addProperty("count",a.size());r.add("adapters",a);return r;}TestStudioAiProvider ai(String id){if(id==null||id.isBlank()){if(ai.isEmpty())throw new IllegalStateException("No Test Studio AI provider is installed");return ai.getFirst();}return ai.stream().filter(p->p.id().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("AI provider not found: "+id));}DatabaseAdapter database(String product,String driver){return databases.stream().filter(p->p.supports(product,driver)).findFirst().orElseThrow(()->new IllegalStateException("No Test Studio database adapter supports "+product+" / "+driver));}private static <T>void load(String point,Class<T> type,java.util.function.Consumer<T> sink){IExtensionRegistry r=Platform.getExtensionRegistry();if(r==null)return;for(IConfigurationElement e:r.getConfigurationElementsFor(point))try{Object o=e.createExecutableExtension("class");if(type.isInstance(o))sink.accept(type.cast(o));}catch(Exception ignored){}}}
